'use client'

import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from 'react'
import Button from './Button'

/**
 * A random slot picker that shows the games: a horizontal reel of cover art
 * that tears away and crawls to a stop on the drawn slot, like a case opening.
 *
 * The catalogue is public/slots.json, Stake's full slots list regenerated by
 * scripts/update-slots.mjs:
 *   { updated, providers: [name, ...], games: [[name, slug, img, providerIndex, onlyOnStake?], ...] }
 * `img` is a mediumrare.imgix.net asset id (Stake's image CDN), or a full URL
 * for the few hosted elsewhere. A trailing 1 marks games Stake tags "Only on
 * Stake".
 *
 * The winner is drawn before the animation starts and the strip is built
 * around it, so the roll is decoration: a dropped frame can't change the
 * result. The parent drives it through the ref (spin / clear) so the page's
 * own Randomize and Reset buttons can stay where they are.
 */

export type Slot = {
  name: string
  slug: string
  img: string
  provider: string
  exclusive: boolean
}

type Row = [string, string, string, number] | [string, string, string, number, 1]
type Catalogue = { updated: string; providers: string[]; games: Row[] }

export type SlotReelHandle = { spin: () => void; clear: () => void }

const IMGIX = 'https://mediumrare.imgix.net/'
const CARD_W = 150
const GAP = 12
const STRIDE = CARD_W + GAP
const SPIN_MS = 6000
const SPIN_EASING = 'cubic-bezier(0.10, 0.82, 0.16, 1)'
const RUNWAY = 34 // cards that ride past before the winner lands
const LEAD = 6 // cards already left of the marker at spin start
const TOP_CHIPS = 16
const MAX_MATCHES = 60

const smallCut = 'polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px)'

export function slotImage(img: string, w: number, h: number) {
  if (!img) return ''
  return img.startsWith('http') ? img : `${IMGIX}${img}?w=${w}&h=${h}&fit=min&auto=format`
}

// Unbiased random integer in [0, max): rejection sampling, like the roller.
function randInt(max: number): number {
  if (max <= 1) return 0
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) {
    const limit = Math.floor(0x100000000 / max) * max
    const u = new Uint32Array(1)
    do {
      crypto.getRandomValues(u)
    } while (u[0] >= limit)
    return u[0] % max
  }
  return Math.floor(Math.random() * max)
}

// Search ignores case, spaces and punctuation, so "nolimit" finds "No Limit City".
const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '')

const toSlot = (r: Row, providers: string[]): Slot => ({
  name: r[0],
  slug: r[1],
  img: r[2],
  provider: providers[r[3]] ?? 'Other',
  exclusive: r[4] === 1,
})

const SlotReel = forwardRef<
  SlotReelHandle,
  {
    /** Fires as a spin starts, so the page can clear the previous round. */
    onSpinStart?: () => void
    /** Fires when the reel stops, with the drawn slot. */
    onLand?: (slot: Slot) => void
    /** Rendered under the result: the page puts its "→ FinBuck / → Chat" buttons here. */
    actions?: React.ReactNode
    /** Called once the catalogue loads, so the page can look slots up by name. */
    onCatalogue?: (slots: Slot[]) => void
  }
>(function SlotReel({ onSpinStart, onLand, actions, onCatalogue }, ref) {
  const [cat, setCat] = useState<Catalogue | null>(null)
  const [loadError, setLoadError] = useState('')
  // Starts on Stake's own "Only on Stake" games; the toggle opens up the full catalogue.
  const [onlyStake, setOnlyStake] = useState(true)
  const [selected, setSelected] = useState<Set<number>>(() => new Set())
  const [query, setQuery] = useState('')
  const [showFilter, setShowFilter] = useState(false)

  const [strip, setStrip] = useState<Slot[]>([])
  const [spinning, setSpinning] = useState(false)
  const [landed, setLanded] = useState<Slot | null>(null)
  const [spinSeq, setSpinSeq] = useState(0)

  const trackRef = useRef<HTMLDivElement | null>(null)
  const viewRef = useRef<HTMLDivElement | null>(null)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const motionRef = useRef({ start: 0, end: 0 })

  useEffect(() => {
    let alive = true
    fetch('/slots.json')
      .then((r) => {
        if (!r.ok) throw new Error(String(r.status))
        return r.json() as Promise<Catalogue>
      })
      .then((data) => {
        if (!alive) return
        setCat(data)
        onCatalogue?.(data.games.map((g) => toSlot(g, data.providers)))
      })
      .catch(() => alive && setLoadError('Could not load the slot catalogue. Refresh to try again.'))
    return () => {
      alive = false
      if (timerRef.current) clearTimeout(timerRef.current)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // Games in scope (all, or Only on Stake), then per-provider counts for the chips.
  const scoped = useMemo(() => (cat ? (onlyStake ? cat.games.filter((g) => g[4] === 1) : cat.games) : []), [cat, onlyStake])
  const counts = useMemo(() => {
    const c = cat ? cat.providers.map(() => 0) : []
    for (const g of scoped) c[g[3]]++
    return c
  }, [cat, scoped])
  const pool = useMemo(
    () => (cat ? (selected.size ? scoped.filter((g) => selected.has(g[3])) : scoped).map((g) => toSlot(g, cat.providers)) : []),
    [cat, scoped, selected],
  )

  const pick = (arr: Slot[]) => arr[randInt(arr.length)]

  // Fill a strip at random without repeating a neighbour, so the reel never
  // visibly stutters on a duplicate as it slows down.
  function buildStrip(length: number) {
    const out: Slot[] = []
    for (let i = 0; i < length; i++) {
      let g = pick(pool)
      let guard = 0
      while (pool.length > 1 && g === out[i - 1] && guard++ < 12) g = pick(pool)
      out.push(g)
    }
    return out
  }

  const centerOn = (i: number) => (viewRef.current?.offsetWidth ?? 0) / 2 - CARD_W / 2 - i * STRIDE

  // Idle strip: a random sample parked on its middle card. Rebuilt when the
  // pool changes (and not mid-spin).
  const poolKey = pool.length + ':' + onlyStake + ':' + Array.from(selected).join(',')
  useEffect(() => {
    if (spinning) return
    if (!pool.length) {
      setStrip([])
      return
    }
    setStrip(buildStrip(24))
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [poolKey, spinning])

  useEffect(() => {
    if (spinning) return
    const el = trackRef.current
    if (!el || !strip.length) return
    el.style.transition = 'none'
    el.style.transform = `translateX(${centerOn(Math.floor(strip.length / 2))}px)`
  }, [strip, spinning])

  // Run the roll once the spin strip has rendered.
  useEffect(() => {
    if (!spinning) return
    const el = trackRef.current
    if (!el) return
    const { start, end } = motionRef.current
    el.style.transition = 'none'
    el.style.transform = `translateX(${start}px)`
    // Force reflow so the jump lands before the animated transform, or the
    // browser coalesces the two and nothing moves.
    void el.offsetWidth
    const raf = requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        el.style.transition = `transform ${SPIN_MS}ms ${SPIN_EASING}`
        el.style.transform = `translateX(${end}px)`
      }),
    )
    return () => cancelAnimationFrame(raf)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [spinSeq])

  function spin() {
    if (spinning || !pool.length) return
    onSpinStart?.()
    const winner = pick(pool)
    const s = buildStrip(RUNWAY + LEAD + 8)
    s[RUNWAY] = winner
    // Land somewhere in the middle 60% of the card, not dead centre every time.
    const jitter = ((randInt(61) - 30) / 100) * CARD_W
    motionRef.current = { start: centerOn(LEAD), end: centerOn(RUNWAY) + jitter }
    setLanded(null)
    setStrip(s)
    setSpinning(true)
    setSpinSeq((n) => n + 1)
    if (timerRef.current) clearTimeout(timerRef.current)
    timerRef.current = setTimeout(() => {
      setSpinning(false)
      setLanded(winner)
      onLand?.(winner)
    }, SPIN_MS + 80)
  }

  function clear() {
    if (timerRef.current) clearTimeout(timerRef.current)
    setSpinning(false)
    setLanded(null)
  }

  useImperativeHandle(ref, () => ({ spin, clear }))

  // ── Provider chips ──
  const providers = cat?.providers ?? []
  const keys = useMemo(() => providers.map(norm), [providers])
  const ranked = useMemo(
    () =>
      providers
        .map((_, i) => i)
        .filter((i) => counts[i] > 0 || selected.has(i))
        .sort((a, b) => counts[b] - counts[a] || a - b),
    [providers, counts, selected],
  )
  const q = norm(query)
  const hits = q ? ranked.filter((i) => keys[i].includes(q)) : []
  const chips = q
    ? hits.slice(0, MAX_MATCHES)
    : (() => {
        const top = ranked.filter((i) => counts[i] > 0).slice(0, TOP_CHIPS)
        return ranked.filter((i) => top.includes(i) || selected.has(i))
      })()
  const available = counts.filter((c) => c > 0).length

  function toggleProvider(i: number) {
    if (spinning) return
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(i)) next.delete(i)
      else next.add(i)
      return next
    })
  }

  const stakeOnlyCount = cat ? cat.games.filter((g) => g[4] === 1).length : 0
  const poolLine = !cat
    ? loadError || 'Loading slots…'
    : !pool.length
      ? `No ${onlyStake ? 'Stake-only ' : ''}slots from ${selected.size === 1 ? 'this provider' : 'these providers'}.`
      : `${pool.length.toLocaleString('en-US')} ${onlyStake ? 'Stake-only ' : ''}slot${pool.length === 1 ? '' : 's'} in the pool · ${
          selected.size ? `${selected.size} provider${selected.size === 1 ? '' : 's'}` : 'all providers'
        }`

  return (
    <div className="w-full">
      {/* Reel viewport: a sunken well, the marker in green */}
      <div ref={viewRef} className="relative h-[250px] w-full overflow-hidden border-b border-white/[0.06] bg-[#080A20]">
        <div ref={trackRef} className="absolute left-0 top-5 flex will-change-transform" style={{ gap: GAP }}>
          {strip.map((g, i) => (
            <div key={i} className="shrink-0 overflow-hidden bg-[#0B0E2A]" style={{ width: CARD_W, clipPath: smallCut }}>
              {g.img ? (
                // eslint-disable-next-line @next/next/no-img-element
                <img
                  src={slotImage(g.img, 300, 400)}
                  alt=""
                  loading="lazy"
                  draggable={false}
                  className="block h-[180px] w-[150px] select-none bg-[#131740] object-cover"
                />
              ) : (
                <div className="font-display flex h-[180px] w-[150px] items-center justify-center p-2 text-center text-[1.1rem] leading-none text-muted">
                  {g.name}
                </div>
              )}
              <div className="truncate px-2 py-1.5 text-[11px] font-semibold text-muted">{g.name}</div>
            </div>
          ))}
        </div>

        {/* Centre marker */}
        <div
          className="pointer-events-none absolute bottom-0 left-1/2 top-0 z-20 w-[3px] -translate-x-1/2"
          style={{
            background: 'linear-gradient(180deg, transparent, #00FF87 14%, #00FF87 86%, transparent)',
            boxShadow: '0 0 14px rgba(0,255,135,0.8)',
          }}
        />
        <div className="pointer-events-none absolute left-1/2 top-0 z-20 -translate-x-1/2">
          <svg width="18" height="11" viewBox="0 0 18 11"><path d="M0 0 L18 0 L9 11 Z" fill="#00FF87" /></svg>
        </div>
        <div className="pointer-events-none absolute bottom-0 left-1/2 z-20 -translate-x-1/2">
          <svg width="18" height="11" viewBox="0 0 18 11"><path d="M0 11 L18 11 L9 0 Z" fill="#00FF87" /></svg>
        </div>

        {/* Edge fades */}
        <div className="pointer-events-none absolute inset-y-0 left-0 z-10 w-[14%] bg-gradient-to-r from-[#080A20] to-transparent" />
        <div className="pointer-events-none absolute inset-y-0 right-0 z-10 w-[14%] bg-gradient-to-l from-[#080A20] to-transparent" />

        {!strip.length && (
          <p className="absolute inset-0 flex items-center justify-center text-sm text-faint">{poolLine}</p>
        )}
      </div>

      <div className="p-5 sm:p-6">
        {/* Result */}
        {landed ? (
          <div className="flex flex-col items-center gap-5 text-center sm:flex-row sm:text-left">
            {landed.img && (
              // eslint-disable-next-line @next/next/no-img-element
              <img
                src={slotImage(landed.img, 240, 320)}
                alt=""
                className="h-40 w-[120px] shrink-0 bg-[#131740] object-cover"
                style={{ clipPath: smallCut }}
              />
            )}
            <div className="min-w-0 flex-1">
              <p className="text-[10px] font-bold uppercase tracking-[0.3em] text-accent-bright">The slot</p>
              <p className="font-display mt-1 break-words text-[2.2rem] leading-[0.95] text-white sm:text-[2.6rem]">{landed.name}</p>
              <p className="mt-1.5 text-sm text-muted">
                {landed.provider}
                {landed.exclusive && (
                  <span className="ml-2 inline-block bg-accent/15 px-2 py-0.5 text-[10px] font-bold uppercase tracking-[0.18em] text-accent-bright" style={{ clipPath: smallCut }}>
                    Only on Stake
                  </span>
                )}
              </p>
              {actions && <div className="mt-4 flex flex-wrap items-center justify-center gap-2 sm:justify-start">{actions}</div>}
            </div>
          </div>
        ) : (
          <p className="text-center text-sm text-muted">
            {spinning ? 'Rolling…' : cat ? poolLine : loadError || 'Loading slots…'}
          </p>
        )}

        {/* Filter by provider */}
        {cat && (
          <div className="mt-5 border-t border-white/[0.06] pt-5">
            <div className="flex flex-wrap items-center justify-between gap-3">
              <button
                type="button"
                onClick={() => setShowFilter((v) => !v)}
                className="inline-flex items-center gap-2 text-[10px] font-bold uppercase tracking-[0.3em] text-faint transition-colors hover:text-white"
                aria-expanded={showFilter}
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2.2} className={`h-3 w-3 transition-transform ${showFilter ? 'rotate-90' : ''}`} aria-hidden>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M9 5l7 7-7 7" />
                </svg>
                Filter by provider
                {selected.size > 0 && <span className="text-accent-bright">· {selected.size}</span>}
              </button>

              {/* Scope toggle */}
              <div className="flex bg-[#080A20] p-1" style={{ clipPath: smallCut }} role="radiogroup" aria-label="Scope">
                {([false, true] as const).map((v) => (
                  <button
                    key={String(v)}
                    type="button"
                    role="radio"
                    aria-checked={onlyStake === v}
                    disabled={spinning}
                    onClick={() => setOnlyStake(v)}
                    className={`px-3 py-1.5 text-[11px] font-bold transition-colors ${
                      onlyStake === v ? 'bg-accent text-[#0B0E2A]' : 'text-muted hover:text-white'
                    }`}
                    style={{ clipPath: smallCut }}
                  >
                    {v ? 'Only on Stake' : 'All slots'}{' '}
                    <span className={onlyStake === v ? 'opacity-70' : 'text-faint'}>
                      {(v ? stakeOnlyCount : cat.games.length).toLocaleString('en-US')}
                    </span>
                  </button>
                ))}
              </div>
            </div>

            {showFilter && (
              <div className="mt-4">
                <div className="flex gap-2">
                  <input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Search providers…"
                    className="field !h-10 text-sm"
                  />
                  <Button onClick={() => setSelected(new Set())} disabled={spinning || selected.size === 0} variant="ghost" size="sm">
                    Clear
                  </Button>
                </div>
                <div className="mt-3 flex max-h-44 flex-wrap gap-2 overflow-y-auto pr-1">
                  {chips.length === 0 ? (
                    <span className="text-xs text-faint">No providers match.</span>
                  ) : (
                    chips.map((i) => {
                      const on = selected.has(i)
                      return (
                        <button
                          key={i}
                          type="button"
                          onClick={() => toggleProvider(i)}
                          disabled={spinning}
                          aria-pressed={on}
                          className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-[12px] font-semibold transition-colors disabled:opacity-60 ${
                            on ? 'bg-accent text-[#0B0E2A]' : 'bg-white/[0.06] text-muted hover:bg-white/[0.1] hover:text-white'
                          }`}
                          style={{ clipPath: smallCut }}
                        >
                          {providers[i]}
                          <span className={`text-[10px] ${on ? 'opacity-70' : 'text-faint'}`}>{counts[i]}</span>
                        </button>
                      )
                    })
                  )}
                </div>
                <p className="mt-2 text-[11px] text-faint">
                  {q
                    ? hits.length > MAX_MATCHES
                      ? `Showing ${MAX_MATCHES} of ${hits.length} matches. Keep typing to narrow it down.`
                      : ''
                    : available > TOP_CHIPS
                      ? `Top ${TOP_CHIPS} of ${available.toLocaleString('en-US')} providers. Search to find the rest.`
                      : ''}
                </p>
              </div>
            )}

            <p className="mt-3 text-[11px] text-faint">
              {cat.games.length.toLocaleString('en-US')} slots from Stake&apos;s catalogue · updated {cat.updated}. Some games may be
              unavailable in your region.
            </p>
          </div>
        )}
      </div>
    </div>
  )
})

export default SlotReel
